bool oom_reap_task_mm(struct task_struct *tsk, struct mm_struct *mm)
{
    bool success = false;
    struct vm_area_struct *vma;

    down_read(&mm->mmap_lock);

    if (!atomic_read(&mm->mm_users)) {
        up_read(&mm->mmap_lock);
        return false;
    }

    if (atomic_read(&mm->oom_skip)) {
        up_read(&mm->mmap_lock);
        return false;
    }

    atomic_set(&mm->oom_skip, 1);

    for (vma = mm->mmap; vma; vma = vma->vm_next) {
        if (vma->vm_flags & (VM_ANON | VM_SHARED))
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
    }

    success = true;

    atomic_set(&mm->oom_skip, 0);
    up_read(&mm->mmap_lock);

    return success;
}

bool reap_task_mm(struct task_struct *tsk, struct mm_struct *mm) {
    bool success = false;

    task_lock(tsk);
    if (down_read_trylock(&mm->mmap_lock)) {
        if (!atomic_read(&mm->mm_count) || (mm->oom_skip && !has_memory_notifier(mm))) {
            up_read(&mm->mmap_lock);
            task_unlock(tsk);
            return false;
        }

        mm->oom_reaping = true;

        struct vm_area_struct *vma;
        for (vma = mm->mmap; vma; vma = vma->vm_next) {
            if ((vma->vm_flags & (VM_ANON | VM_SHARED)) == VM_ANON) {
                unmap_anon_vma(vma);
            }
        }

        mm->oom_reaping = false;
        up_read(&mm->mmap_lock);
        success = true;
    }

    task_unlock(tsk);
    return success;
}

bool reap_task_mm(struct task_struct *tsk, struct mm_struct *mm) {
    down_read(&mm->mmap_lock);
    if (atomic_read(&mm->mm_count) < 1) {
        up_read(&mm->mmap_lock);
        return false;
    }

    if (test_bit(MMF_OOM_SKIP, &mm->flags)) {
        up_read(&mm->mmap_lock);
        return false;
    }

    set_bit(MMF_UNSTABLE, &mm->flags);

    struct vm_area_struct *vma, *vma_next;
    for (vma = mm->mmap; vma; vma = vma_next) {
        vma_next = vma->vm_next;
        if (vma->vm_flags & (VM_ANON | VM_SHARED)) {
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
        }
    }

    clear_bit(MMF_OOM_SKIP, &mm->flags);
    up_read(&mm->mmap_lock);
    return true;
}

